-- 023 · Biblioteca con GIF: 750 ejercicios de FitCron
-- ----------------------------------------------------------------------
-- Carga la lista de FitCron (planilla FitCron_750.xlsx) en la biblioteca,
-- cada uno con su GIF animado. Los GIF viven dentro de la app
-- (public/ejercicios/fitcron-N.webp, con su versión chica en
-- public/ejercicios/mini), así que "imagen_url" guarda una dirección
-- corta como '/ejercicios/fitcron-12.webp'.
--
-- Qué hace:
--   1) Suma a "ejercicios" la columna "origen" (de dónde vino el
--      ejercicio, por ejemplo 'fitcron-12'). Sirve para no duplicar nada si
--      este archivo se corre de nuevo, aunque el profe haya cambiado el
--      nombre de alguno.
--   2) Si ya había un ejercicio con el mismo nombre (sin importar
--      mayúsculas), no crea otro: le pone el GIF (solo si no tenía foto).
--   3) Crea los que faltan, con su grupo muscular y sus categorías.
--   4) A los ejercicios que ya estaban cargados de antes (SQL 004) y tienen
--      un equivalente claro en FitCron les pone ese GIF, solo si todavía no
--      tenían foto (por ejemplo "Sentadilla trasera" ← "Sentadilla con
--      Barra"). No cambia nombres, categorías ni rutinas.
--   5) Muestra un resumen: tienen que ser 750 de FitCron.
--
-- Cambios de nombre respecto a la planilla (para que no haya dos iguales):
-- los 8 de cuello llevan "(cuello)" y los 7 nombres que FitCron repite en
-- dos grupos llevan el grupo entre paréntesis (por ejemplo "Fondos en
-- Máquina (tríceps)" y "Fondos en Máquina (pecho)").
--
-- No borra nada. Se puede correr más de una vez sin romper nada.

-- 1) Columna "origen" -------------------------------------------------------
alter table public.ejercicios add column if not exists origen text;
create unique index if not exists ejercicios_origen_unico on public.ejercicios (origen);

-- Lista de FitCron (tabla temporal: desaparece sola al terminar) -----------
drop table if exists pg_temp.carga_fitcron;
create temporary table carga_fitcron (
  origen text primary key,
  nombre text not null,
  grupo_muscular text not null,
  categorias text[] not null,
  imagen_url text not null
);


-- 2) Los que ya existían con el mismo nombre: se usan (no se duplican) ------
with coincidencias as (
  select distinct on (c.origen) c.origen, c.imagen_url, e.id
  from carga_fitcron c
  join public.ejercicios e
    on lower(btrim(e.nombre)) = lower(c.nombre) and e.origen is null
  where not exists (select 1 from public.ejercicios x where x.origen = c.origen)
  order by c.origen, e.creado_en
)
update public.ejercicios e
set origen = m.origen,
    imagen_url = coalesce(e.imagen_url, m.imagen_url)
from coincidencias m
where e.id = m.id;

-- 3) Los nuevos --------------------------------------------------------------
select c.origen, c.nombre, c.grupo_muscular, c.categorias, c.imagen_url
from carga_fitcron c
where not exists (select 1 from public.ejercicios e where e.origen = c.origen)
  and not exists (select 1 from public.ejercicios e where lower(btrim(e.nombre)) = lower(c.nombre));

drop table if exists pg_temp.carga_fitcron;

-- 4) GIF para los ejercicios de antes que tienen un equivalente claro -------
