-- 5) Resumen -----------------------------------------------------------------
select
  count(*) filter (where origen like 'fitcron-%') as ejercicios_fitcron,
  count(*) filter (where imagen_url is not null) as con_foto,
  count(*) as total_biblioteca
from public.ejercicios;
